<div class="page-title"><div><em>BANKING</em><h1><?=tl('accounts_title')?></h1><p><?=tl('accounts_sub')?></p></div><button class="btn" data-modal="account-modal"><?=tl('open_account')?></button></div><div class="account-grid"><?php foreach($accounts as $i=>$a):?><article class="account-card <?=$i%2?'teal':''?>"><small><?=strtoupper($a['type'])?> · <?=$a['currency']?></small><h3><?=html_escape($a['name'])?></h3><span>•••• <?=substr($a['account_number'],-4)?></span><strong><?=money($a['available_balance'],$a['currency'])?></strong><p>Available balance <b>›</b></p><div class="card-actions"><button class="btn card-details" data-base="<?=site_url('accounts')?>" data-accid="<?=$a['id']?>" data-accstatus="<?=html_escape($a['status'])?>" data-accprimary="<?=$a['is_primary']?>" data-accnum="<?=html_escape($a['account_number'])?>" data-acctype="<?=strtoupper($a['type'])?>" data-accname="<?=html_escape($a['name'])?>" data-routing="<?=html_escape($routing_number)?>">◉ Details</button><button class="btn card-deposit" data-account-id="<?=$a['id']?>" data-account-name="<?=html_escape($a['name'])?>">↓ Deposit</button></div></article><?php endforeach?><article class="add-card"><i>+</i><h3>Add another account</h3><p>Explore checking, savings and investment options.</p><button data-modal="account-modal">Explore accounts</button></article></div><section class="panel"><div class="panel-head"><div><h2>Account summary</h2><p>Combined balances across your products</p></div></div><div class="summary"><div><span><?=tl('total_assets')?></span><b><?=money(array_sum(array_column($accounts,'available_balance')))?></b></div><div><span><?=tl('monthly_income')?></span><b><?=money($summary['income'])?></b></div><div><span><?=tl('monthly_expenses')?></span><b><?=money($summary['expenses'])?></b></div><div><span><?=tl('active_accounts')?></span><b><?=count($accounts)?></b></div></div></section>
<dialog id="account-modal"><div class="dialog-head"><h2>Open a new account</h2><button data-close>×</button></div><?=form_open('accounts/create')?><label>Account name</label><input name="name" placeholder="e.g. Travel savings"><div class="form-grid"><div><label>Type</label><select name="type"><option value="checking">Checking</option><option value="savings">Savings</option><option value="investment">Investment</option></select></div><div><label>Currency</label><select name="currency"><option value="USD">USD</option><option value="EUR">EUR</option><option value="GBP">GBP</option></select></div></div><label>Opening deposit (optional)</label><input name="opening_balance" type="number" step="0.01" min="0" placeholder="0.00"><button class="btn wide">Open account</button></form></dialog>
<dialog id="deposit-modal"><div class="dialog-head"><h2><?=tl('deposit')?></h2><button data-close>×</button></div><?=form_open('accounts/deposit')?><input type="hidden" name="account_id" id="deposit-account-id"><label>Account</label><input id="deposit-account-name" disabled><label>Amount</label><input name="amount" type="number" step="0.01" min="0.01" required placeholder="0.00"><button class="btn wide">Complete deposit</button></form></dialog>
<dialog id="details-modal"><div class="dialog-head"><h2><?=tl('account_details')?></h2><button data-close>×</button></div><div class="acc-details"><div class="acc-detail-row"><small>ACCOUNT</small><b id="det-name"></b></div><div class="acc-detail-row"><small>TYPE</small><b id="det-type"></b></div><div class="acc-detail-row reveal"><small><?=strtoupper(tl('account_number'))?></small><div class="reveal-wrap"><b id="det-number" class="reveal-hidden">•••• •••• •••• ••••</b><button type="button" class="reveal-btn" data-target="det-number">👁 Show</button></div></div><div class="acc-detail-row reveal"><small><?=strtoupper(tl('routing_number'))?></small><div class="reveal-wrap"><b id="det-routing" class="reveal-hidden">•••• •••• ••••</b><button type="button" class="reveal-btn" data-target="det-routing">👁 Show</button></div></div><p class="field-hint">Use these numbers for direct deposits and wire transfers.</p><div class="acc-status-control" id="acc-status-control" hidden></div></div></dialog>
<script>document.querySelectorAll('.card-deposit').forEach(function(b){b.addEventListener('click',function(){document.getElementById('deposit-account-id').value=b.dataset.accountId;document.getElementById('deposit-account-name').value=b.dataset.accountName;document.getElementById('deposit-modal').showModal();});});
document.querySelectorAll('.card-details').forEach(function(b){b.addEventListener('click',function(){document.getElementById('det-name').textContent=b.dataset.accname;document.getElementById('det-type').textContent=b.dataset.acctype;document.getElementById('det-number').textContent=b.dataset.accnum;document.getElementById('det-routing').textContent=b.dataset.routing;
var sc=document.getElementById('acc-status-control');if(parseInt(b.dataset.accprimary)){sc.hidden=true;sc.innerHTML='';}else{sc.hidden=false;var status=b.dataset.accstatus;var opts='';['active','frozen','closed'].forEach(function(s){opts+='<option value="'+s+'"'+(s===status?' selected':'')+'>'+s.charAt(0).toUpperCase()+s.slice(1)+'</option>';});sc.innerHTML='<h2 style="margin:18px 0 4px">Account status</h2><form method="post" action="'+b.dataset.base+'/'+b.dataset.accid+'/status" class="inline-controls" style="margin:6px 0"><select name="status">'+opts+'</select><button class="btn">Update</button></form>';}
document.getElementById('details-modal').showModal();});});
document.querySelectorAll('.reveal-btn').forEach(function(btn){btn.addEventListener('click',function(){var t=document.getElementById(btn.dataset.target);var hidden=t.classList.contains('reveal-hidden');t.classList.toggle('reveal-hidden',!hidden);btn.textContent=hidden?'🙈 Hide':'👁 Show';});});</script>